/** Qualified prepared negatives distinguish input/effect scope from an unqualified raw-parser refusal. */
class LmdbGenericPreparedFilterReadScopeTest {

	private static final int ROWS = 128;
	private static final String PATTERN = "?s <urn:prepared-filter:p> ?v";
	private static final String CONDITION = "STRSTARTS(STR(?v), \"hit:\")";
	private static final String QUERY = "SELECT ?s ?v WHERE { " + PATTERN + " FILTER(" + CONDITION + ") }";
	@TempDir
	File directory;
	private LmdbStore store;
	private SailRepository repository;

	enum Surface {
		NULLABLE_DEPENDENT,
		PROJECTED_ALIAS,
		UNDEF_PARAMETER,
		UNKNOWN_EFFECT
	}

	@BeforeEach
	void setUp() {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc");
		config.setNativeEvaluationEnabled(false);
		config.setExperimentalQueryOptimizations(true);
		config.setFrontierEstimatorMode(FrontierEstimatorMode.OFF);
		config.setOptimizerSamplingEnabled(false);
		config.setBackgroundRawSamplingMaxMillisPerCycle(0L);
		store = new LmdbStore(directory, config);
		repository = new SailRepository(store);
		repository.init();
		try (var connection = repository.getConnection()) {
			var vf = connection.getValueFactory();
			connection.begin();
			for (int i = 0; i < ROWS; i++) {
				connection.add(vf.createIRI("urn:prepared-filter:s:" + i), vf.createIRI("urn:prepared-filter:p"),
						vf.createLiteral((i % 4 == 0 ? "hit:" : "miss:") + i));
			}
			connection.commit();
		}
	}

	@AfterEach
	void tearDown() {
		repository.shutDown();
	}

	@ParameterizedTest
	@EnumSource(Surface.class)
	void preparedGraphQualifiedDifferentSurfaceCannotBorrowTheCensus(Surface surface) {
		try (Read read = open()) {
			train(read);
			Filter baseline = onlyFilter(prepare(read, QUERY));
			assertLearned(read.statistics.estimateFilterPass(baseline));
			FilterSurfaceKey baselineKey = FilterSurfaceKey.exact(baseline);
			assertThat(baselineKey).isNotNull();
			TupleExpr prepared = prepare(read, different(surface));
			List<Filter> residuals = filters(prepared);
			assertThat(residuals).as("the actual entry must retain a residual for this refusal fixture: %s", surface)
					.isNotEmpty();
			var identity = LmdbFilterOutcomeFeedbackDescriptor.readIdentity(
					read.statistics.estimatorRuntime(), read.source, null);
			assertThat(identity).as("same actual unmodified source is independently authenticated").isNotNull();
			for (Filter filter : residuals) {
				assertScopePremise(surface, filter);
				assertThat(PlanningGraphDomains.domain(filter).allowsNativeEvidence())
						.as("UNKNOWN graph scope must not supply the refusal: %s", surface)
						.isTrue();
				assertThat(FilterSurfaceKey.exact(filter))
						.as("fixture retains a different normalized input/effect surface: %s", surface)
						.isNotEqualTo(baselineKey);
				assertThat(store.getBackingStore()
						.learnedFilterSelectivity()
						.estimateQualified(
								store.getBackingStore().valueStore(),
								read.statistics.estimatorRuntime().snapshotVersion(),
								filter, identity)).as("qualified namespace refuses this different surface: %s", surface)
										.isNull();
				assertThat(read.statistics.estimateFilterPass(filter).getSource())
						.as("actual source-bound facade retains the same refusal: %s", surface)
						.isNotIn(FilterPassEstimate.Source.LEARNED_FILTER, FilterPassEstimate.Source.LEARNED_TEMPLATE,
								FilterPassEstimate.Source.LEARNED_PATTERN);
			}
		}
	}

	@Test
	void validNullableNormalizationRetainsTheSameQualifiedCensus() {
		try (Read read = open()) {
			train(read);
			Filter baseline = onlyFilter(prepare(read, QUERY));
			assertLearned(read.statistics.estimateFilterPass(baseline));
			String query = "SELECT ?s ?v WHERE { " + PATTERN
					+ " OPTIONAL { ?s <urn:prepared-filter:q> ?extra } FILTER(" + CONDITION + ") }";
			List<Filter> residuals = filters(prepare(read, query));
			Filter normalized = residuals.stream()
					.filter(filter -> FilterSurfaceKey.exact(baseline).equals(FilterSurfaceKey.exact(filter)))
					.findFirst()
					.orElseThrow(() -> new AssertionError(
							"existing left-only OPTIONAL filter placement must retain its valid single-pattern surface"));
			assertThat(PlanningGraphDomains.domain(normalized).allowsNativeEvidence()).isTrue();
			assertLearned(read.statistics.estimateFilterPass(normalized));
		}
	}

	@Test
	void factoryBindingAloneDoesNotAuthorizeRawParserGraphScope() {
		try (Read read = open()) {
			train(read);
			Filter raw = onlyFilter(parse(QUERY));
			assertThat(PlanningGraphDomains.domain(raw).allowsNativeEvidence()).isFalse();
			assertThat(read.statistics.estimateFilterPass(raw).getSource())
					.isNotIn(FilterPassEstimate.Source.LEARNED_FILTER, FilterPassEstimate.Source.LEARNED_TEMPLATE,
							FilterPassEstimate.Source.LEARNED_PATTERN);
			assertLearned(read.statistics.estimateFilterPass(onlyFilter(prepare(read, QUERY))));
		}
	}

	private static String different(Surface surface) {
		return switch (surface) {
		case NULLABLE_DEPENDENT -> "SELECT ?s WHERE { " + PATTERN
				+ " OPTIONAL { ?s <urn:prepared-filter:q> ?extra } FILTER(" + CONDITION + " || !BOUND(?extra)) }";
		case PROJECTED_ALIAS -> "SELECT ?s WHERE { { SELECT ?s (CONCAT(STR(?v), \"!\") AS ?projected) WHERE { "
				+ PATTERN + " } } FILTER(STRSTARTS(?projected, \"hit:\")) }";
		case UNDEF_PARAMETER -> "SELECT ?s WHERE { VALUES (?parameter ?unused) { (\"hit:\" UNDEF) (UNDEF \"x\") } "
				+ PATTERN + " FILTER(STRSTARTS(STR(?v), COALESCE(?parameter, \"miss:\"))) }";
		case UNKNOWN_EFFECT -> "SELECT ?s WHERE { " + PATTERN + " FILTER(<urn:prepared-filter:unknown-function>(?v)) }";
		};
	}

	private static void assertScopePremise(Surface surface, Filter filter) {
		var required = VarNameCollector.process(filter.getCondition());
		switch (surface) {
		case NULLABLE_DEPENDENT -> {
			assertThat(required).contains("extra");
			assertThat(filter.getArg().getBindingNames()).contains("extra");
			assertThat(filter.getArg().getAssuredBindingNames()).doesNotContain("extra");
		}
		case PROJECTED_ALIAS -> {
			assertThat(required).contains("projected");
			assertThat(filter.getArg().getBindingNames()).contains("projected");
			assertThat(filter.getArg().getAssuredBindingNames()).doesNotContain("projected");
		}
		case UNDEF_PARAMETER -> {
			assertThat(required).contains("parameter");
			assertThat(filter.getArg().getBindingNames()).contains("parameter");
			assertThat(filter.getArg().getAssuredBindingNames()).doesNotContain("parameter");
		}
		case UNKNOWN_EFFECT -> assertThat(ScalarEvaluationEffects.effectOf(filter.getCondition()))
				.isEqualTo(ScalarEvaluationEffects.Effect.UNKNOWN);
		}
	}

	private void train(Read read) {
		TupleExpr optimized = read.strategy.optimize(parse(QUERY), read.statistics, EmptyBindingSet.getInstance());
		List<String> actual = QueryResults.asList(
				read.strategy.precompile(optimized).evaluate(EmptyBindingSet.getInstance()))
				.stream()
				.map(row -> row.getValue("s").stringValue() + "|" + ((Literal) row.getValue("v")).getLabel())
				.toList();
		List<String> expected = new ArrayList<>();
		for (int i = 0; i < ROWS; i += 4) {
			expected.add("urn:prepared-filter:s:" + i + "|hit:" + i);
		}
		assertThat(actual).hasSize(ROWS / 4).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(store.getBackingStore().learnedFilterSelectivity().size()).isPositive();
	}

	private TupleExpr prepare(Read read, String query) {
		return new LmdbQueryOptimizerPipeline(read.strategy, read.source, read.statistics).withPreparedQueryEntry(
				parse(query), null, EmptyBindingSet.getInstance(), (prepared, cascades) -> prepared);
	}

	private Read open() {
		SailDataset dataset = store.getBackingStore().getExplicitSailSource().dataset(IsolationLevels.SNAPSHOT_READ);
		try {
			SailDatasetTripleTermSource source = new SailDatasetTripleTermSource(store.getValueFactory(), dataset);
			LmdbEvaluationStatistics statistics = (LmdbEvaluationStatistics) store.getBackingStore()
					.getEvaluationStatistics();
			EvaluationStrategy strategy = store.getConnectionEvaluationStrategyFactory()
					.createEvaluationStrategy(
							null, source, statistics, store.getQueryExecutionPolicy());
			assertThat(source.getClass()).isEqualTo(SailDatasetTripleTermSource.class);
			assertThat(source.getSnapshotEpoch()).isPresent();
			assertThat(strategy).isInstanceOf(LmdbEvaluationStrategy.class)
					.isNotInstanceOf(LmdbNativeEvaluationStrategy.class);
			assertThat(strategy.getQueryExecutionPolicy().experimentalQueryOptimizations()).isTrue();
			assertThat(statistics.estimatorRuntime().frontierSettings().mode()).isEqualTo(FrontierEstimatorMode.OFF);
			assertThat(statistics.estimatorRuntime().statisticsService() == null
					|| statistics.estimatorRuntime().statisticsService().currentManifest().isEmpty()).isTrue();
			((LmdbEvaluationStrategy) strategy).setTrackResultSize(true);
			return new Read(dataset, source, statistics, strategy);
		} catch (RuntimeException | Error failure) {
			try {
				dataset.close();
			} catch (RuntimeException | Error cleanupFailure) {
				if (failure != cleanupFailure) {
					failure.addSuppressed(cleanupFailure);
				}
			}
			throw failure;
		}
	}

	private static void assertLearned(FilterPassEstimate estimate) {
		assertThat(estimate.getSource()).isIn(FilterPassEstimate.Source.LEARNED_FILTER,
				FilterPassEstimate.Source.LEARNED_TEMPLATE, FilterPassEstimate.Source.LEARNED_PATTERN);
		assertThat(estimate.getPassRatio()).isCloseTo(0.25d, within(1e-12d));
		assertThat(estimate.getEvidenceCount()).isEqualTo(ROWS);
	}

	private static TupleExpr parse(String query) {
		return QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
	}

	private static Filter onlyFilter(TupleExpr expression) {
		List<Filter> filters = filters(expression);
		assertThat(filters).hasSize(1);
		return filters.getFirst();
	}

	private static List<Filter> filters(TupleExpr expression) {
		List<Filter> result = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Filter filter) {
				result.add(filter);
				super.meet(filter);
			}
		});
		return result;
	}

	private record Read(SailDataset owner, SailDatasetTripleTermSource source, LmdbEvaluationStatistics statistics,
			EvaluationStrategy strategy) implements AutoCloseable {
		@Override
		public void close() {
			owner.close();
		}
	}
}
